style.css:
@-moz-document domain("pikabu.ru") {
/* Pikabu ships a fully tokenised design system (~900 CSS custom properties).
     The cleanest, most stable retheme is to flip the light palette tokens to a
     dark equivalent at :root, then add a thin structural safety net for the few
     surfaces that use literal colours or inherit a transparent background from
     the body. Brand green and semantic colours (vote up/down, badges, awards)
     are preserved — only their tone is refined to sit well on the dark canvas. */

  :root {
    color-scheme: dark !important;

    /* ---- Local palette ---- */
    --pk-bg: #14181d;            /* base canvas */
    --pk-surface: #1c2128;       /* elevated cards (stories, comments) */
    --pk-surface-2: #1a1f26;     /* secondary surface (inputs, chips) */
    --pk-header: #0d1117;        /* header / footer */
    --pk-border: #2a313a;        /* subtle borders */
    --pk-border-soft: #232931;   /* very subtle dividers */
    --pk-text: #e6edf3;          /* primary text */
    --pk-text-soft: #c4cdd6;     /* body text */
    --pk-text-muted: #8b949e;    /* muted / hints / placeholder */
    --pk-green: #8fd35c;          /* refined Pikabu green (brand) */
    --pk-green-hover: #a4e072;
    --pk-green-deep: #6fae44;

    /* ---- Flip the "bright"/"blackjack"/"black" greyscale ramps ----
       Pikabu's neutral ramps run light→dark; we re-map the light end of each to
       dark surfaces and the dark end to light text, so every component built on
       these tokens themes itself. */
    --color-bright-900: var(--pk-surface);
    --color-bright-800: var(--pk-surface);
    --color-linear-bright-900: var(--pk-surface);
    --color--header__bg: var(--pk-header);
    --footer-bg: var(--pk-header);

    --color-blackjack-100: var(--pk-surface);   /* was #fcfdff */
    --color-blackjack-99: var(--pk-bg);          /* was #f7f8fc */
    --color-blackjack-97: var(--pk-surface-2);   /* was #f2f3f7 */
    --color-blackjack-90: var(--pk-border);      /* was #dfe1e5 */
    --color-blackjack-75: #6b7480;
    --color-blackjack-70: var(--pk-text-muted);  /* was #aaacb2 */
    --color-blackjack-60: var(--pk-text-muted);  /* was #909299 */
    --color-blackjack-50primary: #9aa3ad;        /* was #757880 */
    --color-blackjack-30: var(--pk-text-soft);   /* was #45474d */
    --color-blackjack-18: var(--pk-text);        /* was #292a2e */
    --color-blackjack-15: var(--pk-text);        /* was #222326 */
    --color-blackjack-10: var(--pk-text);        /* was #1f2021 */

    --color-black-100: var(--pk-surface);        /* was #f9f9fb */
    --color-black-200: var(--pk-surface);        /* was #f9f9fb */
    --color-black-300: var(--pk-bg);             /* was #f7f8fc */
    --color-black-400: var(--pk-border);         /* was #e9e9e9 */
    /* NOT a surface token: black-420 is only ever used as `color`, for the label on
       the video-player scrim. Pikabu keeps it #e9e9e9 in its own dark theme too. */
    --color-black-420: #e9e9e9;
    --color-black-430: var(--pk-border);         /* was #ebedf2 */
    --color-black-440: var(--pk-border);
    --color-black-500: #4a525c;                  /* was #d8dadd */
    --color-black-600: #7d8893;                  /* was #b0b3bb */
    --color-black-700: #aab3bd;                  /* was #70737b */
    --color-black-800: var(--pk-text-soft);      /* was #444850 */
    --color-black-900: var(--pk-text);           /* was #212121 */
    --color-black-920: var(--pk-text);
    --color-black-940: var(--pk-text);           /* body text was #1b1e24 */

    /* ---- Background / surface design tokens ---- */
    --s-colorBg-clear: var(--pk-surface);
    --s-colorBg-tonned: var(--pk-bg);
    --s-colorBg-stroke: var(--pk-border);
    --s-colorBg-special: #2a2718;
    --s-colorBg-popup: rgba(0, 0, 0, 0.64);

    --s-text-heading-primary: var(--pk-text);
    --s-text-paragraph-primary: var(--pk-text);
    --s-text-paragraph-secondary: var(--pk-text-soft);
    --s-text-subheading-primary: var(--pk-text);
    --s-text-label-primary: var(--pk-text-soft);
    --s-text-label-secondary: var(--pk-text-muted);
    --s-text-label-tertiary: var(--pk-text-muted);
    --user-name-text: var(--pk-text);

    /* ---- Inputs / textareas / comboboxes / selects ---- */
    --c-input-bgDefault: var(--pk-surface-2);
    --c-input-bgDisabled: var(--pk-bg);
    --c-input-strokeDefault: var(--pk-border);
    --c-input-textDefault: var(--pk-text-muted);
    --c-textarea-bgDefault: var(--pk-surface-2);
    --c-textarea-bgDisabled: var(--pk-bg);
    --c-textarea-strokeDefault: var(--pk-border);
    --c-textarea-textFilled: var(--pk-text);
    --c-combobox-bgDefault: var(--pk-surface-2);
    --c-combobox-bgDisabled: var(--pk-bg);
    --c-combobox-content-bg: var(--pk-bg);
    --c-combobox-strokeDefault: var(--pk-border);
    --c-combobox-content-stroke: var(--pk-border);
    --c-combobox-contentDefault: var(--pk-text-muted);
    --c-combobox-contentFilled: var(--pk-text);
    --c-combobox-contentDisabled: var(--pk-text-muted);
    /* Suggestion list (tag/author filters). Only rendered once the field is focused
       and typed into, so no load-time scan sees it: the item label kept #292a2e and
       the matched substring a pale #eaffd9 chip — invisible / glaring on the dark list. */
    --c-combobox-list-textPrimary: var(--pk-text-soft);
    --c-combobox-list-textSecondary: var(--pk-text-muted);
    --c-combobox-list-hover: var(--pk-surface);
    --c-combobox-list-click: var(--pk-border);
    --c-combobox-searchBg: #3a4d2a;
    --c-select-main-bgDefault: var(--pk-surface-2);
    --c-select-main-bgDisabled: var(--pk-bg);
    --c-select-main-strokeDefault: var(--pk-border);
    --c-select-list-bg: var(--pk-surface);
    --c-select-list-item-text: var(--pk-text);
    /* The Select/Dropdown panel paints itself from --c-select-list-item-default (NOT
       -bg). It is portaled into <body> only while open, so a load-time scan never sees
       it: the panel stayed #fcfdff white under our light item text. */
    --c-select-list-item-default: var(--pk-surface);
    --c-select-list-item-hover: var(--pk-surface-2);
    --c-select-list-item-click: var(--pk-border);
    --c-selectBtn-bgDefault: var(--pk-surface-2);
    --c-selectBtn-bgHover: var(--pk-surface);
    --c-selectBtn-stroke: var(--pk-border);

    /* ---- Tags / chips / quotes / tooltips / menus ---- */
    --c-tag-bgDefault: var(--pk-surface-2);
    --c-tag-bgHover: var(--pk-surface);
    --c-tag-bgContrastDefault: var(--pk-surface-2);
    --c-tag-bgContrastHover: var(--pk-surface);
    --c-tag-stroke: var(--pk-border);
    --c-tag-strokeContrast: var(--pk-border);
    --c-quote-bg: var(--pk-surface-2);
    --c-tooltip-bg: var(--pk-surface);
    --c-tooltip-text: var(--pk-text);
    --c-menu-item-text: var(--pk-text);
    --c-menu-item-hover: var(--pk-surface-2);
    --c-menu-item-click: var(--pk-border);
    --c-counter-bgTertiary: var(--pk-surface-2);
    /* filled counters keep a light brand/alert fill — flip their label dark to read */
    --c-counter-text: var(--pk-bg);

    /* ---- Secondary buttons (neutral greys) ---- */
    --c-btn-secondary-bgDefault: var(--pk-surface-2);
    --c-btn-secondary-bgHover: var(--pk-border);
    --c-btn-secondary-bgClick: var(--pk-border);
    --c-btn-secondary-textIcon: var(--pk-text-soft);
    --c-btnIcon-tertiary-bgDefault: var(--pk-surface-2);
    --c-btnIcon-tertiary-bgHover: var(--pk-surface);
    --c-btnIcon-tertiary-stroke: var(--pk-border);
    --c-btnSocialIcon-bgDefault: var(--pk-surface-2);
    --c-btnSocialIcon-bgHover: var(--pk-surface);
    --c-btnSocialIcon-bgClick: var(--pk-border);
    --c-social-bgWhite: var(--pk-surface);

    /* ---- Pagination ---- */
    --c-pagination-defaultBg: var(--pk-surface-2);
    --c-pagination-hoverBg: var(--pk-surface);
    --c-pagination-clickBg: var(--pk-border);
    --c-pagination-content: var(--pk-text-soft);

    /* ---- Alerts / captcha / collapse ---- */
    --c-alert-baseBg: var(--pk-surface-2);
    --c-alert-baseStroke: var(--pk-border);
    --c-captcha-block-bg: var(--pk-surface-2);
    --c-captcha-block-stroke: var(--pk-border);
    --collapse-stroke: var(--pk-border);
    --c-bottomSheet-line: var(--pk-border);

    /* ---- Refine the brand green (keep hue family, lift for dark) ---- */
    --color-pikabu-80primary: var(--pk-green);
    --color-pikabu-75: var(--pk-green);
    --color-pikabu-60: var(--pk-green-deep);
    --color-primary-800: var(--pk-green);
    --color-primary-700: var(--pk-green);
    --color-primary-600: var(--pk-green);
    --color-primary-900: var(--pk-green-deep);
    --c-btn-primary-bgDefault: var(--pk-green);
    --c-btn-primary-bgHover: var(--pk-green-hover);
    --c-btn-primary-bgClick: var(--pk-green-deep);
    --c-btn-primaryText-textIcon: var(--pk-green);
    --c-navigation-horizontal-textActiveDefault: var(--pk-green);
    --c-counter-bgPrimary: var(--pk-green);
    --c-counter-textPrimary: var(--pk-green);
    --c-breadcrumbs-default: var(--pk-green);
    --s-colorTextSpecial-accent: var(--pk-green);

    /* ---- Rating: keep green up / red down, lift the tone for dark ---- */
    --rating-plus-active: var(--pk-green);
    --rating-plus-hover: var(--pk-green);
    --rating-plus-default: var(--pk-text-muted);
    --rating-plus-click: var(--pk-green-deep);
    --rating-minus-active: #ef6a5d;
    --rating-minus-hover: #ef6a5d;
    --rating-minus-default: var(--pk-text-muted);
    --rating-minus-click: #d9483b;
    --rating-progressMinus: #ef6a5d;
    --rating-icon: var(--pk-text-muted);
    --rating-text: var(--pk-text-muted);
    --rating-stroke: var(--pk-border);
    --rating-progressBg: var(--pk-border);
    --reaction-default: var(--pk-surface-2);
    --reaction-hover: var(--pk-surface);

    /* ---- Subtle shadows: soften so they don't glow on dark ---- */
    --shadow-low: 0 1px 12px rgba(0, 0, 0, 0.4);
    --s-shadow-mainStroke: rgba(255, 255, 255, 0.06);
    --s-shadow-extraStroke: rgba(255, 255, 255, 0.06);
  }

  /* ===== Base canvas ===== */
  html { background-color: var(--pk-bg) !important; }
  body {
    background-color: var(--pk-bg) !important;
    color: var(--pk-text-soft) !important;
  }

  /* ===== Borders ===== (colour only — never adds a border, safe everywhere) */
  * { border-color: var(--pk-border) !important; }

  /* ===== Header ===== */
  .header,
  .header__inner,
  .header_with-ads,
  .app-header {
    background-color: var(--pk-header) !important;
    border-color: var(--pk-border) !important;
  }
  .header a,
  .header__nav a,
  .menu__link,
  .header-menu a { color: var(--pk-text-soft) !important; }
  .header a:hover,
  .menu__link:hover { color: var(--pk-text) !important; }
  .header-dropdown,
  .header-menu__dropdown,
  .menu-popup,
  .dropdown__content { background-color: var(--pk-surface) !important; }

  /* ===== Main columns / feed wrappers (transparent over base) ===== */
  .app,
  .layout,
  .layout__content,
  .main,
  .wrapper,
  .page,
  .page__inner,
  .stories-feed,
  .stories-feed__container,
  .feed,
  .sidebar,
  .sidebar_right,
  .sidebar_left { background-color: transparent !important; }

  /* ===== Story / post cards ===== */
  .story,
  .story__main,
  .story-block,
  .page-story,
  .page-story__main { background-color: var(--pk-surface) !important; }
  .story__title,
  .story__title-link,
  .story-title,
  .page-story__title { color: var(--pk-text) !important; }
  .story__content-inner,
  .story__text,
  .story-block__content,
  .b-story-block__text { color: var(--pk-text-soft) !important; }
  .story__title-link:hover { color: var(--pk-green-hover) !important; }

  /* "Primary" colour text posts: the author picks a coloured background that is
     painted on .story__content-inner (with a decorative white-gloss overlay we
     keep). Our generic .story-block surface rule forced the nested text block to
     a dark surface, laying an opaque band across the middle of the coloured post.
     Keep the inner text block transparent so the author's colour shows through. */
  [class*="story_primary"] .story-block,
  [class*="story_primary"] .story-block_type_text { background-color: transparent !important; }

  /* Rating block on the story card */
  .story__rating-block { background-color: var(--pk-surface-2) !important; }
  .story__rating-count { color: var(--pk-text-soft) !important; }

  /* ===== Tags ===== */
  .tags__tag,
  .story__tags a,
  a.tag {
    background-color: var(--pk-surface-2) !important;
    color: var(--pk-text-soft) !important;
    border-color: var(--pk-border) !important;
  }
  .tags__tag:hover,
  .story__tags a:hover { background-color: var(--pk-surface) !important; color: var(--pk-text) !important; }

  /* Tag STATE variants carry meaning, and the blanket label colour above swallowed
     all three: `_nsfw` is the adult-content warning (danger red), `_added` /
     `_removed` mark a tag just added to / removed from your filters (green / red).
     Pikabu paints them from --color-danger-900 / --color-primary-900. Restore each,
     dark-tuned. The selectors must outrank our own `.story__tags a` rule (0,1,1),
     hence the doubled class / `.story__tags a…` forms. */
  .tags__tag.tags__tag_nsfw,
  .story__tags a.tags__tag_nsfw,
  a.tag_nsfw,
  .tags__tag.tags__tag_removed,
  .story__tags a.tags__tag_removed,
  a.tag_removed { color: #ef6a5d !important; }
  .tags__tag.tags__tag_added,
  .story__tags a.tags__tag_added,
  a.tag_added { color: var(--pk-green) !important; }

  /* ===== Comments tree ===== */
  .comments,
  .page-story__comments { background-color: var(--pk-surface) !important; }
  .comment,
  .comment__content,
  .comment__body { background-color: transparent !important; color: var(--pk-text-soft) !important; }
  .comment__user,
  .comment .user__nick { color: var(--pk-text) !important; }
  .comment-toolbar,
  .comments__sorting,
  .comment__children { background-color: transparent !important; }
  /* the thin nesting guide-lines between nested comments */
  .comment__branch,
  .comment__indent,
  .comment-thread__line { border-color: var(--pk-border) !important; background-color: var(--pk-border) !important; }

  /* Pikabu marks the comment you wrote yourself with a filled username pill:
     `[data-own=true]` paints it from --color-black-700, a mid-grey (#70737b) that
     carried a white label. We lift that token to #aab3bd (it is a TEXT tone
     everywhere else), which turns the pill into a light grey slab under our light
     label — 1.3:1, effectively invisible. Give the pill its own dark fill so the
     "this is mine" marker survives. The OP pill ([data-own-story]) keeps its brand
     green, matching every other green fill on this theme. */
  .comment__user[data-own="true"] .user__nick {
    background-color: #4a525c !important;
    color: var(--pk-text) !important;
  }

  /* ===== Author / user blocks, avatars (do NOT tint the avatar image) ===== */
  .user__nick,
  .story__user-link,
  a.user { color: var(--pk-text) !important; }
  .avatar img,
  .user__avatar img,
  img.avatar { background-color: transparent !important; }

  /* ===== Search ===== */
  input[type="text"],
  input[type="search"],
  input[name="q"],
  .search-input,
  .input__field,
  textarea {
    background-color: var(--pk-surface-2) !important;
    color: var(--pk-text) !important;
    border-color: var(--pk-border) !important;
  }
  input::placeholder,
  textarea::placeholder { color: var(--pk-text-muted) !important; }
  .search-results,
  .search__results,
  .search-suggest { background-color: var(--pk-surface) !important; }

  /* ===== Login form — third-party provider buttons ===== */
  /* The provider buttons (VK / Yandex ID) keep their brand background, but their label
     is painted with --color-bright-900, which this theme remaps to a dark tone — on the
     black Yandex button that is near-invisible. Pin the label light. */
  .auth__provider-text,
  [class*="auth__provider"] .auth__provider-text { color: var(--pk-text) !important; }

  /* ===== Filter / sort / tab / segmented controls =====
     These interactive controls hardcode a near-black label colour (#292a2e /
     #37393d) for their UNSELECTED state, which is invisible on the dark canvas.
     Make every unselected label clearly readable (body-text tone), and keep the
     SELECTED/active state visually distinct (brand green or white-on-green) so
     the affordance is preserved. */

  /* Home feed sort tabs (Горячее / Лучшее / Свежее / Подписки) */
  .header-menu__item,
  .header-menu__item a,
  .header-menu a { color: var(--pk-text-soft) !important; }
  .header-menu__item:hover,
  .header-menu__item:hover a { color: var(--pk-text) !important; }
  /* current/selected feed sort stays brand green + bolder */
  .header-menu__item_current,
  .header-menu__item_current a,
  .header-menu__item_active,
  .header-menu__item_active a { color: var(--pk-green) !important; font-weight: 600 !important; }

  /* Search result tabs (Посты / Пользователи / Теги / Сообщества) */
  [class*="TabItem__tab"],
  [class*="TabItem__tab"] span { color: var(--pk-text-soft) !important; }
  [class*="TabItem__tab"]:hover { color: var(--pk-text) !important; }
  /* The pill background is painted by the tab's ::before pseudo, which hardcodes
     a near-white #fcfdff for unselected tabs (and brand green for the active one).
     Remap the unselected pill to a dark elevated surface so the light label reads,
     and refresh the active pill with the dark-tuned brand green. */
  [class*="TabItem__tab"]::before {
    background-color: var(--pk-surface-2) !important;
    border-color: var(--pk-border) !important;
  }
  [class*="TabItem__tab"]:hover::before { background-color: var(--pk-surface) !important; }
  /* The selected tab is marked by a data-tab-active ATTRIBUTE, not a class — the old
     [class*="TabItem__tab_active"] selectors never matched, so our neutral pill above
     painted the selected tab too and it read as unselected. Restore the green pill. */
  [class*="TabItem__tab"][data-tab-active],
  [class*="TabItem__tab"][data-tab-active] span { color: #ffffff !important; font-weight: 600 !important; }
  [class*="TabItem__tab"][data-tab-active]::before {
    background-color: var(--pk-green-deep) !important;
    border-color: var(--pk-green-deep) !important;
  }
  /* Counter pills nested in a tab must not inherit the tab's label colour: the filled
     "primary" counter sits on brand green, where a light label lands at ~1.1:1. The
     doubled attribute selector is needed to outrank the tab's own label rule. */
  [class*="Counter__host"][class*="_primary"],
  [class*="Counter__host"][class*="_primary"] span {
    color: var(--pk-bg) !important;
    -webkit-text-fill-color: var(--pk-bg) !important;
  }

  /* Search period / type segmented buttons (Сегодня / Неделя / Текстовые …) */
  [class*="SelectBtn__button"],
  [class*="SelectBtn__button"] span {
    background-color: var(--pk-surface-2) !important;
    color: var(--pk-text-soft) !important;
    border-color: var(--pk-border) !important;
  }
  [class*="SelectBtn__button"]:hover { background-color: var(--pk-surface) !important; color: var(--pk-text) !important; }
  /* active segmented button keeps the brand green pill with white label */
  [class*="SelectBtn__button_active"],
  [class*="SelectBtn__button_active"] span {
    background-color: var(--pk-green-deep) !important;
    color: #ffffff !important;
    border-color: var(--pk-green-deep) !important;
  }

  /* Comment-sort + generic sorting controls (Лучшие / Новые / Старые …) */
  [class*="comments__sort"],
  [class*="comments__sort"] a,
  [class*="comments__sort"] span,
  [class*="sorting__item"],
  .comments__sorting a,
  .comments__sorting span { color: var(--pk-text-soft) !important; }
  [class*="sorting__item_active"],
  [class*="comments__sort"] .active,
  .comments__sorting .active { color: var(--pk-green) !important; font-weight: 600 !important; }

  /* A DISABLED comment-menu tab (e.g. "Автора" when the OP hasn't commented)
     hardcodes a near-black #2d3236 that was a light grey on the original light
     skin — invisible on the dark menu bar. Lift it to the muted tone so it still
     reads as disabled but is legible. */
  .menu__item_disabled,
  .menu__item_disabled span { color: var(--pk-text-muted) !important; }

  /* The inline "text" Select used as the result-sort trigger (e.g. "Сначала
     свежее") keeps a dark brand-green #598039 that drops below the WCAG floor on
     the dark canvas. Lift only this accent/text Select variant to the dark-tuned
     brand green; neutral dropdown Selects keep their token colours. */
  [class*="Select__host_text"] [class*="Select__label"] { color: var(--pk-green) !important; }

  /* The legacy sort selector on the Communities list ("Сортировать по
     актуальности ⌄") is a plain span.link[data-role="sort"] whose label + Font
     Awesome chevron keep Pikabu's darker brand green #67993d — it lands ~4.2:1 on
     the dark card, just under the WCAG floor, and reads dimmer than the modern
     Select above. Lift it (and its ::before chevron glyph) to the dark-tuned green. */
  span.link[data-role="sort"],
  span.link[data-role="sort"] span,
  span.link[data-role="sort"] i.fa { color: var(--pk-green) !important; }

  /* The "primary-text" ghost + "outline" green-accent button variants (e.g. the
     "Сбросить запрос" reset-query action on an empty search result, and the
     "Расширенный поиск" advanced-search action in the search flyout) hardcode the
     dark brand-green #598039 on their label, which lands ~2.9:1 on the dark card.
     Lift the label to the dark-tuned brand green so the action stays readable, and
     restore the outline variant's green border (our universal border rule flattens
     it to grey, erasing the button's affordance). */
  [class*="Btn__btn_primary-text"],
  [class*="Btn__btn_primary-text"] [class*="label"],
  [class*="Btn__btn_outline"],
  [class*="Btn__btn_outline"] [class*="label"] {
    color: var(--pk-green) !important;
    -webkit-text-fill-color: var(--pk-green) !important;
  }
  [class*="Btn__btn_outline"] { border-color: var(--pk-green-deep) !important; }

  /* Legacy green-outline button (.button_border — the "Поддержать" support/donate
     CTA on profiles and posts). Pikabu ships it as an always-green outline button
     (border: var(--color-primary-700); color: var(--color-primary-900)), but our
     universal `* { border-color }` reset flattened its green ring to grey, erasing
     the affordance and leaving a borderless-looking button. Restore the green ring
     and lift the label to the dark-tuned brand green for readability. */
  .button.button_border,
  button.button_border,
  a.button_border {
    border-color: var(--pk-green-deep) !important;
    color: var(--pk-green) !important;
  }

  /* "Post boost active" badge (green rocket pill on hot posts). It ships a green
     ring around the green-tinted pill; our universal `* { border-color }` reset
     flattened the ring to grey. Restore the green border to complete the signal. */
  .story-boost-badge { border-color: var(--pk-green-deep) !important; }

  /* ===== Sidebar widgets / community blocks ===== */
  .sidebar-block,
  .sidebar-game,
  .community-card,
  .community,
  .b-community,
  .widget,
  .block { background-color: var(--pk-surface) !important; }
  .sidebar-block__title,
  .widget__title,
  .community-card__title { color: var(--pk-text) !important; }

  /* Some sidebar / topic widgets hardcode a dark-grey #292a2e text and a white
     surface as literal values (not tokens), so they survive the :root flip and
     end up dark-on-dark. Restore readable text + dark surfaces explicitly. */
  .sidebar-game__title-text,
  .sidebar-game__name,
  .page-topic-links__name,
  .page-topic-links__title { color: var(--pk-text) !important; }
  .sidebar-game__title-subtext,
  .sidebar-game__genres { color: var(--pk-text-muted) !important; }

  /* The in-feed "Pikabu Игры" carousel variant hardcodes the same near-black
     #292a2e on the widget title + each game name — invisible on the dark card.
     Lift the title/name to readable light text; keep the genre subtitle muted. */
  .feed-games-carousel__title-text,
  .feed-games-carousel__name { color: var(--pk-text) !important; }
  .feed-games-carousel__genres,
  .feed-games-carousel__subtext { color: var(--pk-text-muted) !important; }
  .page-topic-links,
  .page-topic-links__link {
    background-color: var(--pk-surface) !important;
    color: var(--pk-text-soft) !important;
  }
  .page-topic-links__link:hover { background-color: var(--pk-surface-2) !important; color: var(--pk-text) !important; }

  .gamification-btn { background-color: var(--pk-surface-2) !important; }

  /* Purchasable nickname badges. Each variant carries its own identity in
     --badge-shop-{bg,stroke,content}; a flat neutral surface plus the old `.hint`
     muting collapsed all six to the same grey pill. Drive the badge from its own
     tokens and pin each variant to a dark tint with a label above the WCAG floor.
     `!important` on the custom property is required: Pikabu re-declares these under
     :root[data-theme-dark], which outranks a plain override. */
  .pkb-badge-shop {
    /* The BASE token values are Pikabu's light default (#f2f3f7 pill / #5e6066 label),
       and they are what any badge WITHOUT a colour variant resolves to — e.g. the
       neutral `_gray` badge ("неисправен"), which Pikabu never gives a rule of its
       own. Those badges shipped as a white pill on the dark card. Give the base a dark
       default; the six colour variants below are later in this sheet at equal
       specificity, so they still win for the badges that own an identity colour. */
    --badge-shop-bg: #262c34 !important;
    --badge-shop-stroke: #39414b !important;
    --badge-shop-content: #c4cdd6 !important;
    background-color: var(--badge-shop-bg) !important;
    border-color: var(--badge-shop-stroke) !important;
    color: var(--badge-shop-content) !important;
    -webkit-text-fill-color: var(--badge-shop-content) !important;
  }
  .pkb-badge-shop_myata {
    --badge-shop-bg: #11261f !important;
    --badge-shop-stroke: #1d4034 !important;
    --badge-shop-content: #5cb98a !important;
  }
  .pkb-badge-shop_bubblegum {
    --badge-shop-bg: #330d1d !important;
    --badge-shop-stroke: #4d142c !important;
    --badge-shop-content: #e5679c !important;
  }
  .pkb-badge-shop_papaya {
    --badge-shop-bg: #2e1707 !important;
    --badge-shop-stroke: #47240b !important;
    --badge-shop-content: #e58d4e !important;
  }
  .pkb-badge-shop_banana {
    --badge-shop-bg: #1f1d17 !important;
    --badge-shop-stroke: #332f23 !important;
    --badge-shop-content: #e8ba23 !important;
  }
  .pkb-badge-shop_berry {
    --badge-shop-bg: #121633 !important;
    --badge-shop-stroke: #1e254d !important;
    --badge-shop-content: #8b96e8 !important;
  }
  .pkb-badge-shop_sliva {
    --badge-shop-bg: #231233 !important;
    --badge-shop-stroke: #371d4d !important;
    --badge-shop-content: #b98be0 !important;
  }

  /* The "donated" reaction pill keeps a cream #fff3eb fill (Pikabu only darkens it in
     its own dark theme, so a light-OS user gets a glaring island among dark pills). */
  button.emotion-btn_donated,
  .emotion-btn_donated {
    background-color: #2a2318 !important;
    color: #e0975a !important;
    -webkit-text-fill-color: #e0975a !important;
  }
  button.emotion-btn_donated:hover,
  .emotion-btn_donated:hover { background-color: #352c1e !important; }

  /* ===== Generic light surfaces caught by literal colours ===== */
  [style*="background: #fff"],
  [style*="background-color: #fff"],
  [style*="background:#fff"],
  [style*="background-color:#fff"] { background-color: var(--pk-surface) !important; }

  /* ===== Footer ===== */
  .footer,
  .page-footer,
  .b-footer {
    background-color: var(--pk-header) !important;
    color: var(--pk-text-muted) !important;
  }
  .footer a,
  .footer a span,
  .page-footer a,
  [class*="footer"] a,
  [class*="footer__link"],
  [class*="footer-link"] { color: var(--pk-text-soft) !important; }

  /* ===== Code / quotes inside posts ===== */
  pre, code, .b-story-block__code {
    background-color: var(--pk-surface-2) !important;
    color: #a5d6ff !important;
    border-color: var(--pk-border) !important;
  }
  blockquote, .b-quote, .comment__quote {
    background-color: var(--pk-surface-2) !important;
    border-color: var(--pk-border) !important;
    color: var(--pk-text-soft) !important;
  }

  /* ===== Generic muted / hint text =====
     `.hint` is NOT a muted-text class on Pikabu — it marks "this element owns a
     tooltip", and it lands on shop badges, reaction pills and the logo. Muting it
     erased their colours; list the genuinely-muted elements instead. */
  .text-muted, .date, time, .comment__time, .story__date, .story__views {
    color: var(--pk-text-muted) !important;
  }

  /* Several metadata bits (comment counts, result counts, slider captions) use a
     literal mid-grey (#757880 / #45474d) rather than a token, which lands below
     the WCAG floor on dark. Lift them to the readable muted tone. */
  .story__comments-link-count,
  [class*="comments-link-count"],
  [class*="results-stories__count"],
  [class*="results-search__count"],
  [class*="Slider__info"] { color: var(--pk-text-muted) !important; }

  /* The legally-required advertising disclosure ("Реклама: <advertiser> ИНН …")
     on sponsored posts hardcodes a #6a6f76 grey that was fine on the original
     white card but drops to ~3:1 on the dark surface. Lift it to the readable
     muted tone (still low-emphasis, but above the WCAG floor). */
  .story__advert-info-text,
  [class*="advert-info-text"] { color: var(--pk-text-muted) !important; }

  /* Video / embedded-player poster placeholders show a light loading panel
     before the media paints — darken it so it matches the surrounding card. */
  [class*="player-block__preview"],
  [class*="video-file-player__player"],
  [class*="player-block__poster"] { background-color: #0d1117 !important; }

  /* --color-bright-900 (#ffffff) is Pikabu's ALWAYS-white foreground: it paints the
     label/icon of every brand fill, and it stays #ffffff even in Pikabu's own dark
     theme. We remap it to a dark tone at :root so labels read on this theme's
     lightened brand-green fills — but the same token also paints the chrome that
     floats over photos, video scrims and the black image viewer, where a dark tone is
     invisible. Restore the white foreground for those subtrees only. --color-black-440
     rides along: it colours the viewer's help/zoom icons on the same black backdrop. */
  .image-viewer,
  .external-video-viewer,
  .story__adult-overlay,
  .story_overlayed,
  .toast,
  .pls-not-block,
  .image-thumb__information,
  .image-thumb__duration,
  .story-fragment__play,
  .comment-external-video__play,
  .comment-external-video__state,
  .carousel_images .carousel__cur-slide,
  .dnd-overlay__content,
  [class*="player-block__state"] {
    --color-bright-900: #e9e9e9;
    --color-black-440: #e9e9e9;
  }

  /* INVERTED TOKENS USED AS SURFACES.
     --color-black-700/-800/-900/-940 are Pikabu's DARK greys; the palette flip above
     lifts them to light tones because they are text colours nearly everywhere. In a
     handful of places Pikabu instead uses them as a `background-color` — those
     surfaces flip the wrong way and come out near-white on the dark canvas. A DOM
     scan never catches them: every one is a transient, hover-only or state-only
     surface that is not in the tree at load time. Pin each back to a dark fill.
       .image-viewer-loader__stage   the lightbox spinner (a white disc on the black
                                     scrim while a full-size image loads; #444850 natively)
       .popup_warning .popup__container  a natively near-black (#212121) warning modal
       .comment-external-video__state:hover  hover fill on an embedded video's state chip
       .evaluation-emoji__title_framed / .avatar__note_banned / .icon--ui__close_story-preview
       video.player                  the legacy Vue player's letterbox area */
  .image-viewer-loader__stage,
  .evaluation-emoji__title_framed { background-color: #3a4149 !important; }
  .avatar__note_banned,
  .icon--ui__close_story-preview { background-color: var(--pk-border) !important; }
  video.player,
  .comment-external-video__state:hover { background-color: var(--pk-header) !important; }
  /* The warning modal paints its own text from --color-bright-900, which we remap to a
     dark tone — so darkening the container alone would leave it dark-on-dark. Restore
     the light foreground inside it, exactly as for the image viewer above. */
  .popup_warning .popup__container {
    background-color: var(--pk-surface) !important;
    --color-bright-900: #e9e9e9;
  }

  /* Header ad-slot containers default to a literal white background; before an ad
     paints (or when none loads) that flashes a bright strip across the top of
     every page. Darken the empty container — loaded ad creatives paint over it. */
  .ads-placeholder,
  .external_branding,
  [class*="ads-placeholder"] { background-color: var(--pk-bg) !important; }

  /* Highlight marker (author "highlighter" runs + search-term highlights). Its
     original light-yellow background is driven by tokens that the palette flip
     turns into a murky dark olive, while the text stayed near-black — leaving the
     whole highlighted run dark-on-dark and unreadable. Pin a deterministic muted
     dark-gold highlight with light text so the emphasis stays legible on dark. */
  .pkb-marker,
  mark,
  [class*="pkb-marker"] {
    background-color: #4a4327 !important;
    color: var(--pk-text) !important;
    -webkit-text-fill-color: var(--pk-text) !important;
  }
}
